/**
 *  How fresh an account's limits are.
 * 
 *  A plain string for a unit variant, a one-key object for the others; a kind from a newer
 *  Clauseo decodes to `Unknown`.
 */
export type LimitSource = 
/**  Read less than 15 minutes ago. */
({ fresh: {
	/**  When it was read. */
	checked_at: Timestamp,
} }) & { live_only?: never; stale?: never; unavailable?: never } | 
/**  The last good read is older, or the last refresh failed; the numbers show muted. */
({ stale: {
	/**  When the last good read was. */
	checked_at: Timestamp,
	/**  Why it is stale. */
	reason: StaleReason,
} }) & { fresh?: never; live_only?: never; unavailable?: never } | 
/**  The first read has not finished. */
"loading" | 
/**  No numbers are available. */
({ unavailable: {
	/**  Why. */
	reason: UnavailableReason,
} }) & { fresh?: never; live_only?: never; stale?: never } | 
/**  The account pays as it goes; no windows apply. */
"not_applicable" | 
/**
 *  The plan read is gone (the experimental Claude call was removed or reshaped); the
 *  bars come only from the agent's live `_claude/rateLimit` signals during a turn.
 */
({ live_only: {
	/**  When the last live signal arrived. */
	updated_at: Timestamp,
} }) & { fresh?: never; stale?: never; unavailable?: never } | 
/**  A state from a newer Clauseo; written back as the plain string `kind`. */
string;

/**  A turn stopped at the usage limit: the at-limit card. Entry id `limit_stop:<turn>`. */
export type LimitStopEntry = {
	/**  The `seq` of `TurnStoppedAtLimit`. */
	order: Seq,
	/**  The turn. */
	turn: TurnId,
	/**  The limit window's id, if known. */
	window?: string,
	/**  When it resets, if known. */
	resets_at?: Timestamp,
	/**  Which limit. */
	reason: LimitStopReason,
};

/**  Which limit stopped a turn; a reason from a newer Clauseo decodes to `Unknown`. */
export type LimitStopReason = 
/**  A plan window is used up. */
"plan_window" | 
/**  The workspace has no credits left. */
"workspace_credits" | 
/**  The workspace reached its spend cap. */
"workspace_spend_cap" | 
/**  A temporary rate limit. */
"temporary" | 
/**  A value from a newer Clauseo that this version does not know. */
"unknown";

/**  One usage window, such as the 5-hour session or the week. */
export type LimitWindow = {
	/**  The window's id, as the agent names it. */
	id: string,
	/**  What it counts. */
	kind: WindowKind,
	/**  A label, such as "5-hour limit". */
	label: string,
	/**  How much of it is used, 0 to 100. */
	used_percent: Finite,
	/**  When it resets, when known. */
	resets_at?: Timestamp,
	/**  Its length in minutes, when known. */
	duration_mins?: number,
	/**  The agent warned that the limit is near (Claude's `allowed_warning`). */
	warning: boolean,
};

/**  One window's row in the popover and on the settings page. */
export type LimitWindowView = {
	/**  The window's id, matching [`LimitWindow::id`]. */
	id: string,
	/**  What it counts. */
	kind: WindowKind,
	/**  Its label. */
	label: string,
	/**
	 *  How much is used, 0 to 100; `None` while loading or once its reset time passed, so an
	 *  old percentage is never shown as current.
	 */
	used_percent?: Finite,
	/**  Its bar's colour. */
	tone: MeterTone,
	/**  When it resets. */
	resets_at?: Timestamp,
	/**  How fresh this row is. */
	freshness: WindowFreshness,
};

/**  What the UI shows for each signed-in agent: a JSON object keyed by agent kind. */
export type LimitsView = Partial<{ [key in AgentKind]: AgentLimitsView }>;

/**  An undo, a restore or a compaction. Entry id `marker:<event>`. */
export type MarkerEntry = {
	/**  The `seq` of the event it records. */
	order: Seq,
	/**  That event's id. */
	event: EventId,
	/**  What it records. */
	kind: MarkerKind,
};

/**  What a marker records. */
export type MarkerKind = 
/**  A step was undone (thread stream). */
({ step_undone: {
	/**  The step's turn. */
	turn: TurnId,
	/**  The checkpoint the undo wrote. */
	checkpoint: CheckpointId,
	/**  Files put back. */
	restored: MatterPath[],
	/**  Files kept as they were. */
	kept: MatterPath[],
} }) & { compaction?: never; version_restored?: never } | 
/**  A version was restored (matter stream). */
({ version_restored: {
	/**  The checkpoint restored from. */
	from: CheckpointId,
	/**  The checkpoint the restore wrote. */
	checkpoint: CheckpointId,
	/**  What was put back. */
	scope: RestoreScope,
} }) & { compaction?: never; step_undone?: never } | 
/**  The agent compacted its context (thread stream). */
({ compaction: {
	/**  Started or completed. */
	status: CompactionStatus,
	/**  The summary the agent kept, when it sent one. */
	summary?: TextOrBlob,
} }) & { step_undone?: never; version_restored?: never };

/**
 *  A matter was created: the first event of a matter's stream.
 * 
 *  Built through [`MatterCreated::new`], which refuses an import summary on the scratch matter;
 *  decoding accepts any combination, so an older or foreign entry still reads.
 */
export type MatterCreated = {
	/**  The matter's name. */
	name: string,
	/**  How it was made. */
	kind: MatterKind,
	/**  What the import found, for a folder matter. */
	import?: ImportSummary,
};

/**  A matter's header. Entry id `matter_header:<matter>`. */
export type MatterHeaderEntry = {
	/**  The `seq` of `MatterCreated`. */
	order: Seq,
	/**  The matter. */
	matter: MatterId,
	/**  Its name. */
	name: string,
	/**  How it was made. */
	kind: MatterKind,
	/**  What the import found, for a folder matter. */
	import?: ImportSummary,
};

/**
 *  A matter: a folder or a scratch space the lawyer works in.
 * 
 * It must be a v7 UUID.
 */
export type MatterId = string;

/**  How a matter was made. */
export type MatterKind = 
/**  The built-in matter the host creates on first start. */
"scratch" | 
/**  A folder the lawyer chose or created. */
"folder" | 
/**  A value from a newer Clauseo that this version does not know. */
"unknown";

/**
 *  A path inside a matter: `/` separators, no leading `/`, no `\`, no Unicode control
 *  character (`char::is_control`: C0, DEL and C1), no empty, `.` or `..` segment, no drive
 *  form (`C:`, `C:x`, `C:/..`), at most 255 bytes per segment and 4096 bytes in all. Never an
 *  id: commands name files by [`FileRefId`].
 * 
 *  Bidi marks and other format characters are allowed (Hebrew and Arabic file names hold
 *  U+200F), so the UI shows a path bidi-isolated. A `:` elsewhere is allowed, because macOS
 *  file names may hold one. On Windows `matters` must refuse a path with a `:` (an alternate
 *  data stream), a part for which [`is_windows_reserved_name`] is true, and a part ending in
 *  a dot or a space.
 * 
 *  Two paths are the same path only when their bytes are equal: no case folding and no
 *  Unicode normalisation, although APFS and NTFS ignore case and APFS ignores normalisation,
 *  so `café.docx` in NFC and in NFD are two paths here. `matters` and the UI compare paths
 *  the same way, and the host matches an `UndoStep`'s paths against the step's
 *  `FilesChanged` exactly, so a path the file system would read as another file is refused.
 */
export type MatterPath = string;

/**  Where a new matter's folder comes from. Folders are named by the ids the host issued. */
export type MatterSource = 
/**
 *  `folder` is the parent; the host creates `<parent>/<name>`. The name must then also work
 *  as a folder name on every system: at most [`MAX_MATTER_NAME_BYTES`], not `.` or `..`,
 *  no leading dot (Finder hides such a folder), none of `< > : " / \ | ? *`, no leading
 *  space, no trailing dot or space, and not a Windows device name
 *  ([`is_windows_reserved_name`](crate::is_windows_reserved_name)).
 */
({ new_folder: {
	/**  The parent folder. */
	folder: FolderRefId,
} }) & { existing_folder?: never } | 
/**
 *  The matter is an existing folder, which keeps its own name: the matter's name is only a
 *  label and meets the title rules alone, so a folder called `Smith v Jones?` can keep it.
 *  Those rules refuse some folder names that exist: more than
 *  [`MAX_TITLE_CHARS`](crate::MAX_TITLE_CHARS) characters (a folder name may be 255 bytes), a
 *  control character (C0, DEL, C1), a line or paragraph separator (U+2028, U+2029), a bidi
 *  embedding, override or isolate (U+202A to U+202E, U+2066 to U+2069), and a name with no
 *  character that shows. The desktop app shortens or cleans such a name before it pre-fills the
 *  matter's name; the folder is not renamed.
 */
({ existing_folder: {
	/**  The folder. */
	folder: FolderRefId,
} }) & { new_folder?: never };

